def main():
    N = int(sys.stdin.readline())
    S = sys.stdin.readline().strip()
    max_len = N // 2
    answer = 0

    def is_possible(length):
        if length == 0:
            return False
        substr_map = defaultdict(list)
        for i in range(N - length + 1):
            substr = S[i:i+length]
            substr_map[substr].append(i)
        for substr, indices in substr_map.items():
            if len(indices) < 2:
                continue
            first = indices[0]
            last = indices[-1]
            if last >= first + length:
                return True
        return False

    low = 0
    high = max_len
    while low <= high:
        mid = (low + high) // 2
        if is_possible(mid):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1
    print(answer)

