import itertools

def is_palindrome(s):
    return s == s[::-1]

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    min_cost = {}
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        idx += 2
        if s not in min_cost or c < min_cost[s]:
            min_cost[s] = c
    strings = list(min_cost.keys())
    min_total = float('inf')
    k_max = 4  # Adjusted to cover more cases
    for k in range(1, k_max + 1):
        for combo in itertools.product(strings, repeat=k):
            s_concat = ''.join(combo)
            if is_palindrome(s_concat):
                total_cost = sum(min_cost[s] for s in combo)
                if total_cost < min_total:
                    min_total = total_cost
    print(-1 if min_total == float('inf') else min_total)

