import heapq

def is_palindrome(s):
    return s == s[::-1]

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    strings = []
    costs = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx + 1])
        strings.append(s)
        costs.append(c)
        idx += 2

    heap = []
    visited = dict()

    for i in range(N):
        s = strings[i]
        c = costs[i]
        if s not in visited or c < visited[s]:
            heapq.heappush(heap, (c, s))
            visited[s] = c

    while heap:
        current_cost, current_str = heapq.heappop(heap)
        if is_palindrome(current_str):
            print(current_cost)
            return
        for i in range(N):
            new_str = current_str + strings[i]
            new_cost = current_cost + costs[i]
            if new_str not in visited or new_cost < visited.get(new_str, float('inf')):
                visited[new_str] = new_cost
                heapq.heappush(heap, (new_cost, new_str))

    print(-1)

