    K = int(data[1])
    R = int(data[2])
    S = int(data[3])
    P = int(data[4])
    T = data[5]

    points = []
    for c in T:
        if c == 'r':
            points.append([0, P, 0])  # r, p, s
        elif c == 'p':
            points.append([0, 0, S])  # r, p, s
        elif c == 's':
            points.append([R, 0, 0])  # r, p, s

    def get_best_hand(m):
        if m == 'r':
            return 1  # p
        elif m == 'p':
            return 2  # s
        else:  # 's'
            return 0  # r

    total = 0
    prev_choices = []

    for group in range((N + K - 1) // K):
        group_start = group * K
        group_end = min((group + 1) * K, N)
        current_choices = []
        for i in range(group_start, group_end):
            if group == 0:
                m = T[i]
                best_hand = get_best_hand(m)
                current_choices.append(best_hand)
                total += points[i][best_hand]
            else:
                prev_choice = prev_choices[i - K]
                m = T[i]
                best_hand = get_best_hand(m)
                if best_hand != prev_choice:
                    current_choices.append(best_hand)
                    total += points[i][best_hand]
                else:
                    allowed_hands = [0, 1, 2]
                    allowed_hands.remove(prev_choice)
                    max_points = -1
                    best_allowed = 0
                    for h in allowed_hands:
                        if points[i][h] > max_points:
                            max_points = points[i][h]
                            best_allowed = h
                    current_choices.append(best_allowed)
                    total += max_points
        prev_choices.extend(current_choices)

