    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    R = int(data[2])
    S = int(data[3])
    P = int(data[4])
    T = data[5]

    # Mapping of machine's move to points for player's move
    # For each player move (0: r, 1: p, 2: s)
    # and machine's move (r, p, s)
    # points[player_move][machine_move]
    # machine_move: 0 for 'r', 1 for 'p', 2 for 's'
    # player_move: 0 for 'r', 1 for 'p', 2 for 's'
    points = [[0]*3 for _ in range(3)]
    points[0][0] = 0  # r vs r: draw
    points[0][1] = 0  # r vs p: lose
    points[0][2] = R  # r vs s: win
    points[1][0] = P  # p vs r: win
    points[1][1] = 0  # p vs p: draw
    points[1][2] = 0  # p vs s: lose
    points[2][0] = S  # s vs r: lose
    points[2][1] = 0  # s vs p: win
    points[2][2] = 0  # s vs s: draw

    # Convert T to machine_move indices
    machine_moves = [0 if c == 'r' else 1 if c == 'p' else 2 for c in T]

    # Initialize DP
    dp = [[0]*3 for _ in range(N)]

    for i in range(N):
        machine_move = machine_moves[i]
        for m in range(3):
            if i < K:
                # No constraint, just add points
                dp[i][m] = points[m][machine_move]
            else:
                # Look back to i-K
                prev_dp = dp[i-K]
                # Find max_prev where move is not m
                if m == 0:
                    max_prev = max(prev_dp[1], prev_dp[2])
                elif m == 1:
                    max_prev = max(prev_dp[0], prev_dp[2])
                else:
                    max_prev = max(prev_dp[0], prev_dp[1])
                dp[i][m] = max_prev + points[m][machine_move]

    print(max(dp[N-1]))

