def main():
    N, X, D = map(int, sys.stdin.readline().split())
    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return
    D_abs = abs(D)
    ranges = defaultdict(list)
    for k in range(N + 1):
        min_m = k * (k - 1) // 2
        max_m = k * (2 * N - k - 1) // 2
        S_k = X * k + D * min_m
        E_k = X * k + D * max_m
        if D < 0:
            S_k, E_k = E_k, S_k
        r_k = (X * k) % D_abs
        ranges[r_k].append((S_k, E_k))

    total = 0
    for r in ranges:
        ranges_list = sorted(ranges[r], key=lambda x: x[0])
        merged = []
        for start, end in ranges_list:
            if not merged:
                merged.append([start, end])
            else:
                last_start, last_end = merged[-1]
                if start <= last_end:
                    new_start = last_start
                    new_end = max(last_end, end)
                    merged[-1] = [new_start, new_end]
                else:
                    merged.append([start, end])
        for start, end in merged:
            remainder = start % D_abs
            if remainder <= r:
                first_val = start + (r - remainder)
            else:
                first_val = start + (D_abs - (remainder - r))
            if first_val > end:
                continue
            last_val = end - ((end - r) % D_abs)
            count = ((last_val - first_val) // D_abs) + 1
            total += count
    print(total)

