    n, k = map(int, input().split())

    if k % 2 != 0:
        print(0)
        return

    from collections import defaultdict

    # dp is a list of dictionaries, where dp[mask] is a dictionary of sum -> count
    dp = [defaultdict(int) for _ in range(1 << n)]
    dp[0][0] = 1

    for mask in range(1 << n):
        current_sums = dp[mask]
        if not current_sums:
            continue
        m = bin(mask).count('1')
