                contribution = abs(m + 1 - x)
                for s in current_sums:
                    new_s = s + contribution
                    if new_s > k:
                        continue
                    dp[new_mask][new_s] = (dp[new_mask][new_s] + current_sums[s]) % MOD

    full_mask = (1 << n) - 1
    print(dp[full_mask].get(k, 0) % MOD)

