    dp = defaultdict(lambda: defaultdict(int))
    dp[0][0] = 1

    visited = set()
    queue = deque([0])
    visited.add(0)

    while queue:
        mask = queue.popleft()
        for bit in range(n):
            if not (mask & (1 << bit)):
                x = bit + 1
                current_position = bin(mask).count('1') + 1
                contribution = abs(current_position - x)
