                    s_new = s_prev + contribution
                    dp[new_mask][s_new] = (dp[new_mask][s_new] + count) % MOD
                if new_mask not in visited:
                    visited.add(new_mask)
                    queue.append(new_mask)

    full_mask = (1 << n) - 1
    print(dp[full_mask].get(k, 0) % MOD)

