    def dfs(pos, mask, current_sum):
        if pos > n:
            return 1 if current_sum == k else 0
        res = 0
        for i in range(1, n+1):
            if not (mask & (1 << (i-1))):
                new_mask = mask | (1 << (i-1))
                new_sum = current_sum + abs(pos - i)
                res += dfs(pos + 1, new_mask, new_sum)
                res %= MOD
        return res

