def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    M = int(input[idx])
    idx += 1
    edges = []
    for _ in range(M):
        a = int(input[idx])
        idx += 1
        b = int(input[idx])
        idx += 1
        c = int(input[idx])
        idx += 1
        edges.append((a, b, c))

    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    for a, b, c in edges:
        if dist[a-1][b-1] > c:
            dist[a-1][b-1] = c
            dist[b-1][a-1] = c

    # Floyd-Warshall algorithm
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    count = 0
    for a, b, c in edges:
        u = a - 1
        v = b - 1
        flag = False
        for i in range(N):
            for j in range(N):
                if dist[i][u] + c + dist[v][j] == dist[i][j]:
                    flag = True
                    break
                if dist[i][v] + c + dist[u][j] == dist[i][j]:
                    flag = True
                    break
            if flag:
                break
        if not flag:
            count += 1
    print(count)

