    def compare(a, b):
        if a == b:
            return a
        a_val = hand_values[a]
        b_val = hand_values[b]
        if (a_val - b_val) % 3 == 1:
            return a
        else:
            return b

    @lru_cache(maxsize=None)
    def get_winner(s_mod, m):
        if m == 0:
            return s[s_mod]
        power = pow(2, m-1, n)
        right_s_mod = (s_mod + power) % n
        left_winner = get_winner(s_mod, m-1)
        right_winner = get_winner(right_s_mod, m-1)
        winner = compare(left_winner, right_winner)
        return winner

    result = get_winner(0, k)
    print(result)

