from collections import deque

def main():
    N = int(sys.stdin.readline())
    A = []
    for _ in range(N):
        A.append(list(map(int, sys.stdin.readline().split())))

    # Generate all possible matches (u, v) where u < v
    match_id = {}
    index = 0
    for u in range(1, N+1):
        for v in range(u+1, N+1):
            match_id[(u, v)] = index
            index += 1
    total_matches = index

    # Build adjacency list
    adj = [[] for _ in range(total_matches)]

    for i in range(1, N+1):
        for j in range(N-2):
            opponent1 = A[i-1][j]
            opponent2 = A[i-1][j+1]
            # Get match1 and match2
            u1 = min(i, opponent1)
            v1 = max(i, opponent1)
            u2 = min(i, opponent2)
            v2 = max(i, opponent2)
            # Add edge from match1 to match2
            match1 = (u1, v1)
            match2 = (u2, v2)
            if match1 == match2:
                continue  # should not happen as per problem constraints
            from_node = match_id[match1]
            to_node = match_id[match2]
            adj[from_node].append(to_node)

    # Check for cycles using Kahn's algorithm
    in_degree = [0] * total_matches
    for u in range(total_matches):
        for v in adj[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(total_matches):
        if in_degree[i] == 0:
            queue.append(i)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(top_order) != total_matches:
        print(-1)
        return

    # Compute longest path
    dist = [0] * total_matches
    for u in top_order:
        for v in adj[u]:
            if dist[v] < dist[u] + 1:
                dist[v] = dist[u] + 1

    max_days = max(dist) + 1
    print(max_days)

