from functools import lru_cache

def main():
    N = input().strip()
    K = int(input())
    digits = list(map(int, N))
    len_s = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos, cnt, tight, leading_zero):
        if pos == len_s:
            return 1 if (cnt == K and not leading_zero) else 0
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_leading_zero = leading_zero and (d == 0)
            new_cnt = cnt + (1 if d != 0 else 0)
            if new_cnt > K:
                continue
            total += dp(pos + 1, new_cnt, new_tight, new_leading_zero)
        return total

    result = dp(0, 0, True, True)
    print(result)

