from functools import lru_cache

def main():
    N = input().strip()
    K = int(input())
    digits = list(map(int, N))
    n = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, leading_zero):
        if pos == n:
            return 1 if (count == K and not leading_zero) else 0
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            if leading_zero:
                if d == 0:
                    new_leading_zero = True
                    new_count = count
                else:
                    new_leading_zero = False
                    new_count = count + 1
            else:
                new_leading_zero = False
                if d != 0:
                    new_count = count + 1
                else:
                    new_count = count
            total += dp(pos + 1, new_count, new_tight, new_leading_zero)
        return total

    result = dp(0, 0, True, True)
    print(result)

