import sys

def generate_subsets(packages):
    k = len(packages)
    sum_dict = {}
    zero_cost = float('inf')
    for mask in range(1 << k):
        sum_val = 0
        cost = 0
        is_empty = True
        for i in range(k):
            if mask & (1 << i):
                is_empty = False
                sum_val += packages[i][0]
                cost += packages[i][1]
        if not is_empty:
            if sum_val in sum_dict:
                if cost < sum_dict[sum_val]:
                    sum_dict[sum_val] = cost
            else:
                sum_dict[sum_val] = cost
            if sum_val == 0:
                if cost < zero_cost:
                    zero_cost = cost
    return sum_dict, zero_cost

