def main():
    H, W, K = map(int, sys.stdin.readline().split())
    rows = []
    for _ in range(H):
        line = sys.stdin.readline().strip()
        rows.append([int(c) for c in line])

    min_cuts = float('inf')

    # Generate all possible horizontal splits
    for bitmask in range(0, 1 << (H-1)):
        groups = []
        current_start = 0
        for i in range(H-1):
            if (bitmask >> i) & 1:
                groups.append((current_start, i))
                current_start = i + 1
        groups.append((current_start, H-1))
        num_groups = len(groups)

        # Compute column_sums for each group
        column_sums = []
        for (start, end) in groups:
            group_sum = [0] * W
            for j in range(W):
                total = 0
                for r in range(start, end + 1):
                    total += rows[r][j]
                group_sum[j] = total
            column_sums.append(group_sum)

        # Now compute vertical cuts
        current_sums = [0] * num_groups
        vertical_cuts = 0
        for j in range(W):
            # Add current column's sum to current_sums
            for i in range(num_groups):
                current_sums[i] += column_sums[i][j]
            # Check if any exceeds K
            if any(current_sums[i] > K for i in range(num_groups)):
                vertical_cuts += 1
                # Reset current_sums to current column's sum
                current_sums = [column_sums[i][j] for i in range(num_groups)]

        total_cuts = (num_groups - 1) + vertical_cuts
        if total_cuts < min_cuts:
            min_cuts = total_cuts

    print(min_cuts)

