def main():
    H, W, K = map(int, sys.stdin.readline().split())
    n = W - 1
    configs = []
    for mask in range(0, 1 << n):
        valid = True
        for i in range(n - 1):
            if (mask & (1 << i)) and (mask & (1 << (i + 1))):
                valid = False
                break
        if valid:
            configs.append(mask)

    size = W
    T = [[0] * size for _ in range(size)]
    for config in configs:
        bits = [(config >> i) & 1 for i in range(n)]
        for i in range(size):
            left_line = False
            right_line = False
            if i > 0 and bits[i - 1] == 1:
                left_line = True
            if i < size - 1 and bits[i] == 1:
                right_line = True
            if left_line:
                new_i = i - 1
            elif right_line:
                new_i = i + 1
            else:
                new_i = i
            T[i][new_i] += 1

    def multiply(a, b):
        res = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if a[i][k]:
                    for j in range(size):
                        res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD
        return res

    def matrix_pow(mat, power):
        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    T_power = matrix_pow(T, H)
    print(T_power[0][K - 1] % MOD)

