def generate_configurations(W):
    positions = list(range(W-1))
    configurations = []
    def backtrack(start, current):
        configurations.append(set(current))
        for i in range(start, len(positions)):
            if current and positions[i] == positions[-1] + 1:
                continue
            current.append(positions[i])
            backtrack(i+1, current)
            current.pop()
    backtrack(0, [])
    return configurations

def compute_new_pos(prev_pos, config, W):
    if prev_pos == 1:
        right_line_index = prev_pos - 1
        if right_line_index in config:
            return prev_pos + 1
        else:
            return prev_pos
    elif prev_pos == W:
        left_line_index = prev_pos - 2
        if left_line_index in config:
            return prev_pos - 1
        else:
            return prev_pos
    else:
        left_line_index = prev_pos - 2
        right_line_index = prev_pos - 1
        if left_line_index in config:
            return prev_pos - 1
        elif right_line_index in config:
            return prev_pos + 1
        else:
            return prev_pos

