    max_distance = 0

    def bfs(start_i, start_j):
        visited = [[-1 for _ in range(w)] for _ in range(h)]
        q = deque()
        q.append((start_i, start_j))
        visited[start_i][start_j] = 0
        max_dist = 0
        while q:
            x, y = q.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
