                if 0 <= nx < h and 0 <= ny < w:
                    if grid[nx][ny] == '.' and visited[nx][ny] == -1:
                        visited[nx][ny] = visited[x][y] + 1
                        max_dist = max(max_dist, visited[nx][ny])
                        q.append((nx, ny))
        return max_dist

    for i in range(h):
        for j in range(w):
            if grid[i][j] == '.':
                current_max = bfs(i, j)
                if current_max > max_distance:
                    max_distance = current_max

    print(max_distance)

