def main():
    N, X = map(int, sys.stdin.read().split())

    # Precompute layers and patties for levels 0 to N
    layers = [0] * (N + 1)
    patties = [0] * (N + 1)
    layers[0] = 1
    patties[0] = 1
    for i in range(1, N + 1):
        layers[i] = 2 * layers[i-1] + 3
        patties[i] = 2 * patties[i-1] + 1

    def f(L, X):
        if L == 0:
            return 1 if X >= 1 else 0
        T = layers[L-1]
        part1_length = 1 + T
        if X == 1:
            return 0
        elif X <= part1_length:
            return f(L-1, X-1)
        else:
            remaining = X - part1_length
            if remaining == 1:
                return patties[L-1] + 1
            else:
                remaining_after_patty = remaining - 1
                if remaining_after_patty <= T:
                    return patties[L-1] + 1 + f(L-1, remaining_after_patty)
                else:
                    return patties[L-1] + 1 + patties[L-1]

    print(f(N, X))

