from functools import lru_cache

def main():
    N, X = map(int, sys.stdin.readline().split())
    layers = [0] * (N + 1)
    patties = [0] * (N + 1)
    layers[0] = 1
    patties[0] = 1
    for i in range(1, N + 1):
        layers[i] = 2 * layers[i-1] + 3
        patties[i] = 2 * patties[i-1] + 1

    @lru_cache(maxsize=None)
    def f(L, X):
        if X == 0:
            return 0
        if L == 0:
            return 1 if X >= 1 else 0
        if X == 1:
            return 0
        first_part_layers = 1 + layers[L-1]
        if X <= first_part_layers:
            return f(L-1, X-1)
        else:
            total = patties[L-1]
            remaining = X - first_part_layers
            if remaining == 1:
                total += 1
            else:
                if remaining > 1:
                    if (remaining - 1) <= layers[L-1]:
                        total += 1 + f(L-1, remaining - 1)
                    else:
                        total += 1 + patties[L-1]
            return total

    print(f(N, X))

