def main():
    import sys
    from collections import defaultdict

    N = int(sys.stdin.readline())
    dp = [defaultdict(int) for _ in range(N+1)]
    dp[0][(None, None, None)] = 1

    forbidden = {"AGC", "GAC", "ACG"}

    for i in range(N):
        current_states = dp[i]
        for state in current_states:
            count = current_states[state]
            a, b, c_prev = state
            for c in ['A', 'C', 'G', 'T']:
                four_chars = [a, b, c_prev, c]
                valid = True
                # Check original substrings
                for j in range(2):
                    substr = tuple(four_chars[j:j+3])
                    if substr in forbidden:
                        valid = False
                        break
                if not valid:
                    continue
                # Check swaps
                for swap_pos in range(3):
                    swapped = four_chars.copy()
                    swapped[swap_pos], swapped[swap_pos+1] = swapped[swap_pos+1], swapped[swap_pos]
                    for j in range(2):
                        substr = tuple(swapped[j:j+3])
                        if substr in forbidden:
                            valid = False
                            break
                    if not valid:
                        break
                if not valid:
                    continue
                new_state = (b, c_prev, c)
                dp[i+1][new_state] = (dp[i+1][new_state] + count) % MOD

    total = sum(dp[N].values()) % MOD
    print(total)

