from collections import defaultdict

def compute_group_max(group_items):
    n = len(group_items)
    max_val = [0] * (n + 1)
    for i in range(n):
        vi = group_items[i][1]
        for t in range(n, i, -1):
            if max_val[t - 1] + vi > max_val[t]:
                max_val[t] = max_val[t - 1] + vi
    return max_val

def prune(entries):
    if not entries:
        return []
    sorted_entries = sorted(entries, key=lambda x: (-x[0], x[1]))
    pruned = []
    for entry in sorted_entries:
        if not pruned:
            pruned.append(entry)
        else:
            last_value, last_weight = pruned[-1]
            current_value, current_weight = entry
            if current_weight < last_weight:
                pruned.append(entry)
    return pruned

