        items.append((w, v))
    w0 = items[0][0]
    groups = [[] for _ in range(4)]
    for w, v in items:
        if w == w0:
            groups[0].append((w, v))
        elif w == w0 + 1:
            groups[1].append((w, v))
        elif w == w0 + 2:
            groups[2].append((w, v))
        else:
            groups[3].append((w, v))
    group_max_vals = []
    for group in groups:
        group_max_vals.append(compute_group_max(group))
    dp = defaultdict(list)
    dp[0].append((0, 0))
    for i in range(4):
        group = groups[i]
        group_weight = w0 + i
        group_max = group_max_vals[i]
        temp_dp = defaultdict(list)
        for m_prev in dp:
            for (value_prev, weight_prev) in dp[m_prev]:
                for t in range(len(group_max)):
                    new_m = m_prev + t
                    new_value = value_prev + group_max[t]
                    new_weight = weight_prev + t * group_weight
                    temp_dp[new_m].append((new_value, new_weight))
        for m in temp_dp:
            temp_dp[m] = prune(temp_dp[m])
        dp = temp_dp
    max_value = 0
    for m in dp:
        for (value, weight) in dp[m]:
            if weight <= W and value > max_value:
