def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    H = int(input[idx])
    idx += 1
    W = int(input[idx])
    idx += 1

    c = []
    for _ in range(10):
        row = list(map(int, input[idx:idx+10]))
        idx += 10
        c.append(row)

    A = []
    for _ in range(H):
        row = list(map(int, input[idx:idx+W]))
        idx += W
        A.append(row)

    # Build reversed graph
    adj_reversed = [[] for _ in range(10)]
    for j in range(10):
        for i in range(10):
            adj_reversed[j].append((i, c[i][j]))

    # Dijkstra's algorithm on reversed graph starting from 1
    INF = float('inf')
    dist = [INF] * 10
    dist[1] = 0
    heap = [(0, 1)]
    visited = set()

    while heap:
        current_dist, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        for v, cost in adj_reversed[u]:
            if dist[v] > current_dist + cost:
                dist[v] = current_dist + cost
                heapq.heappush(heap, (dist[v], v))

    # Calculate total MP
    total = 0
    for row in A:
        for cell in row:
            if cell != -1:
                total += dist[cell]

    print(total)

