    for i in range(N):
        ai = a[i]
        Ti = max(0, K - ai)
        other_sum = total_sum - ai
        if other_sum < Ti:
            count += 1
            continue
        # Compute DP for other elements
        dp = [False] * (K + 1)
        dp[0] = True
        for num in a:
            if num == ai:
                continue
            for s in range(K, num - 1, -1):
                if dp[s - num]:
                    if not dp[s]:
                        dp[s] = True
        # Find minimal s >= Ti
        min_s = K + 1
        for s in range(Ti, K + 1):
            if dp[s]:
                min_s = s
                break
        if min_s > K:
            count += 1
    print(count)

