def main():
    import sys
    N = sys.stdin.readline().strip()
    len_N = len(N)

    # Precompute prefix sums of digits
    prefix_sum = [0] * (len_N + 1)
    for i in range(1, len_N + 1):
        prefix_sum[i] = prefix_sum[i-1] + int(N[i-1])

    # Precompute trailing nines prefix
    trailing_nines_prefix = [0] * (len_N + 1)
    for i in range(1, len_N + 1):
        if N[i-1] == '9':
            trailing_nines_prefix[i] = trailing_nines_prefix[i-1] + 1
        else:
            trailing_nines_prefix[i] = 0

    min_total = prefix_sum[len_N]

    for k in range(1, len_N + 1):
        m = len_N - k
        if m < 0:
            continue
        if m == 0:
            sum_digits_N_part_plus_1 = 1
        else:
            sum_digits_N_part = prefix_sum[m]
            t = trailing_nines_prefix[m]
            sum_digits_N_part_plus_1 = sum_digits_N_part + (1 - 9 * t)

        x = N[-k:]
        sum_digits_x = sum(int(c) for c in x)
        is_zero = all(c == '0' for c in x)

        if is_zero:
            sum_D = 1
            sum_M = sum_digits_N_part_plus_1
        else:
            sum_D = 9 * k + 1 - sum_digits_x
            sum_M = sum_digits_N_part_plus_1

        total = sum_M + sum_D
        if total < min_total:
            min_total = total

    print(min_total)

