    row_data = []
    for r in range(1, R+1):
        items = rows[r]
        if not items:
            row_data.append([])
            continue
        # Sort items by column
        sorted_items = sorted(items, key=lambda x: x[0])
        row_data.append(sorted_items)

    # Initialize DP
    prev_dp = [0] * (C + 1)  # 1-based indexing

    # Process first row
    for x in range(1, C+1):
        sorted_items = row_data[0]
