        # Extract columns for bisect
        cols = [c for c, v in sorted_items]
        left = bisect.bisect_left(cols, 1)
        right = bisect.bisect_right(cols, x)
        items_in_range = sorted_items[left:right]
        # Extract values and sort in descending order
        values = [v for c, v in items_in_range]
