    input = sys.stdin.read().split()
    idx = 0
    H = int(input[idx])
    idx += 1
    W = int(input[idx])
    idx += 1
    grid = []
    for _ in range(H):
        grid.append(input[idx])
        idx += 1

    left = [[0]*W for _ in range(H)]
    right = [[0]*W for _ in range(H)]
    up = [[0]*W for _ in range(H)]
    down = [[0]*W for _ in range(H)]

    # Compute left
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                left[i][j] = 0
            else:
                if j == 0:
                    left[i][j] = 1
                else:
                    left[i][j] = left[i][j-1] + 1

    # Compute right
    for i in range(H):
        for j in range(W-1, -1, -1):
            if grid[i][j] == '#':
                right[i][j] = 0
            else:
                if j == W-1:
                    right[i][j] = 1
                else:
                    right[i][j] = right[i][j+1] + 1

    # Compute up
    for j in range(W):
        for i in range(H):
            if grid[i][j] == '#':
                up[i][j] = 0
            else:
                if i == 0:
                    up[i][j] = 1
                else:
                    up[i][j] = up[i-1][j] + 1

    # Compute down
    for j in range(W):
        for i in range(H-1, -1, -1):
            if grid[i][j] == '#':
                down[i][j] = 0
            else:
                if i == H-1:
                    down[i][j] = 1
                else:
                    down[i][j] = down[i+1][j] + 1

    max_light = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                total = left[i][j] + right[i][j] + up[i][j] + down[i][j] - 3
                if total > max_light:
                    max_light = total
    print(max_light)

