import sys
import math

MOD = 10**9 + 7

def main():
    N = int(sys.stdin.readline())
    zero_count = 0
    groups = dict()
    for _ in range(N):
        a, b = map(int, sys.stdin.readline().split())
        if a == 0 and b == 0:
            zero_count += 1
        else:
            g = math.gcd(abs(a), abs(b))
            a //= g
            b //= g
            if a == 0:
                if b < 0:
                    b = -b
            else:
                if a < 0:
                    a = -a
                    b = -b
            key = (a, b)
            if key in groups:
                groups[key] += 1
            else:
                groups[key] = 1
    processed = set()
    product = 1
    for key in list(groups.keys()):
        if key in processed:
            continue
        a, b = key
        x = b
        y = -a
        if x == 0 and y == 0:
            perp_key = (0, 0)
        else:
            g_perp = math.gcd(abs(x), abs(y))
            x_perp = x // g_perp
            y_perp = y // g_perp
            if x_perp == 0:
                if y_perp < 0:
                    y_perp = -y_perp
            else:
                if x_perp < 0:
                    x_perp = -x_perp
                    y_perp = -y_perp
            perp_key = (x_perp, y_perp)
        if perp_key in groups and perp_key not in processed:
            cnt_key = groups[key]
            cnt_perp = groups[perp_key]
            ways_key = (pow(2, cnt_key, MOD) - 1) % MOD
            ways_perp = (pow(2, cnt_perp, MOD) - 1) % MOD
            term = (ways_key + ways_perp + 1) % MOD
            product = (product * term) % MOD
            processed.add(key)
            processed.add(perp_key)
        else:
            cnt_key = groups[key]
            ways_key = (pow(2, cnt_key, MOD) - 1) % MOD
            term = (ways_key + 1) % MOD
            product = (product * term) % MOD
            processed.add(key)
    ways_non_zero = (product - 1) % MOD
    answer = (ways_non_zero + zero_count) % MOD
    print(answer)

