import math
from collections import defaultdict

MOD = 10**9 + 7

def normalize(a, b):
    if a == 0 and b == 0:
        return (0, 0)
    g = math.gcd(abs(a), abs(b))
    a //= g
    b //= g
    if a == 0:
        if b < 0:
            b = -b
    else:
        if a < 0:
            a = -a
            b = -b
    return (a, b)

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    zero_count = 0
    direction_counts = defaultdict(int)
    for _ in range(N):
        A = int(input[idx])
        B = int(input[idx + 1])
        idx += 2
        if A == 0 and B == 0:
            zero_count += 1
        else:
            norm = normalize(A, B)
            direction_counts[norm] += 1
    product_non_zero = 1
    processed = set()
    for direction in direction_counts:
        if direction not in processed:
            a, b = direction
            orth_a = -b
            orth_b = a
            orth_norm = normalize(orth_a, orth_b)
            if orth_norm in direction_counts:
                if orth_norm not in processed:
                    count_d = direction_counts[direction]
                    count_orth = direction_counts[orth_norm]
                    term = (pow(2, count_d, MOD) + pow(2, count_orth, MOD) - 1) % MOD
                    product_non_zero = (product_non_zero * term) % MOD
                    processed.add(direction)
                    processed.add(orth_norm)
            else:
                term = pow(2, direction_counts[direction], MOD)
                product_non_zero = (product_non_zero * term) % MOD
                processed.add(direction)
    ans = (product_non_zero - 1 + zero_count) % MOD
    print(ans)

