import math

def log_comb(n, k):
    if k == 0 or k == n:
        return 0.0
    if k > n - k:
        k = n - k
    log_n_fact = n * math.log(n) - n + 0.5 * math.log(2 * math.pi * n)
    log_k_fact = k * math.log(k) - k + 0.5 * math.log(2 * math.pi * k)
    log_nk_fact = (n - k) * math.log(n - k) - (n - k) + 0.5 * math.log(2 * math.pi * (n - k))
    return log_n_fact - log_k_fact - log_nk_fact

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))
    a.sort()
    max_log = -float('inf')
    best_pair = (0, 0)
    for i in range(1, n):
        current = a[i]
        target = current / 2
        pos = bisect.bisect_left(a, target, 0, i)
        candidates = []
        if pos > 0:
            candidates.append(a[pos-1])
        if pos < i:
            candidates.append(a[pos])
        if not candidates:
            continue
        best_j = min(candidates, key=lambda x: abs(x - target))
        log_val = log_comb(current, best_j)
        if log_val > max_log:
            max_log = log_val
            best_pair = (current, best_j)
    print(f"{best_pair[0]} {best_pair[1]}")

