import sys

def compute_m(s):
    if s == 0:
        return 0
    r = s % 9
    if r == 0:
        r = 9
        k = (s // 9) - 1
    else:
        k = s // 9
    return int(str(r) + '9' * k)

def main():
    K = int(sys.stdin.readline())
    numbers = []
    for s in range(1, 136):
        m = compute_m(s)
        numbers.append((m, s))
    # Sort by ratio m/s, then by m
    numbers.sort(key=lambda x: (x[0]/x[1], x[0]))
    for i in range(K):
        print(numbers[i][0])

